<template>
  <div class="bg-effect" aria-hidden="true">

    <!-- Wind streaks -->
    <span
      v-for="s in streaks"
      :key="s.id"
      class="wind-streak"
      :style="s.style"
    />

    <!-- Sword slash arcs: 3 layered SVG paths per slash -->
    <div
      v-for="s in slashes"
      :key="s.id"
      class="slash-wrap"
      :style="s.wrapStyle"
    >
      <svg
        class="slash-svg"
        viewBox="0 0 300 100"
        xmlns="http://www.w3.org/2000/svg"
        overflow="visible"
      >
        <!-- Outer blurred glow -->
        <path :d="s.path" class="s-glow" pathLength="1" :style="s.anim" />
        <!-- Amber mid body -->
        <path :d="s.path" class="s-body" pathLength="1" :style="s.anim" />
        <!-- White-hot core line -->
        <path :d="s.path" class="s-core" pathLength="1" :style="s.anim" />
      </svg>
    </div>

  </div>
</template>

<script lang="ts">
import Vue from 'vue';

function rand(min: number, max: number): number {
  return min + Math.random() * (max - min);
}

/**
 * Cubic bezier arc that curves upward from lower-left to lower-right,
 * mimicking a sword slash arc. The container is later rotated slightly
 * downward so the arc slopes as the user swings.
 */
function genArc(): string {
  const x0  = Math.round(rand(4,  20));
  const y0  = Math.round(rand(65, 85));
  const cx1 = Math.round(rand(50, 110));
  const cy1 = Math.round(rand(8,  28));
  const cx2 = Math.round(rand(185, 248));
  const cy2 = Math.round(rand(8,  28));
  const x3  = Math.round(rand(268, 296));
  const y3  = Math.round(rand(56, 75));
  return `M ${x0} ${y0} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${x3} ${y3}`;
}

export default Vue.extend({
  name: 'BackgroundEffect',
  data() {
    /* ── Wind streaks ──────────────────────────────────────── */
    const streaks = Array.from({ length: 26 }, (_, i) => ({
      id: `w${i}`,
      style: {
        top:               `${rand(1, 98).toFixed(1)}%`,
        width:             `${Math.round(rand(30, 260))}px`,
        height:            i % 5 === 0 ? '2px' : '1px',
        animationDuration: `${rand(2, 7).toFixed(2)}s`,
        animationDelay:    `${rand(0, 16).toFixed(2)}s`,
      },
    }));

    /* ── Slash arcs ────────────────────────────────────────── */
    const slashes = Array.from({ length: 9 }, (_, i) => ({
      id: `s${i}`,
      path: genArc(),
      wrapStyle: {
        top:       `${rand(5, 85).toFixed(1)}%`,
        left:      `${rand(2, 66).toFixed(1)}%`,
        // rotate gives downward slope; scale varies size
        transform: `rotate(${rand(8, 28).toFixed(1)}deg) scale(${rand(0.5, 1.3).toFixed(2)})`,
      },
      anim: {
        animationDuration: `${rand(8, 23).toFixed(2)}s`,
        animationDelay:    `${rand(0, 23).toFixed(2)}s`,
      },
    }));

    return { streaks, slashes };
  },
});
</script>

<style scoped lang="less">
@import '../css/variables.less';

/* ─────────────────────────────────────────────────────────
   Container
───────────────────────────────────────────────────────── */
.bg-effect {
  position: fixed;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

/* ─────────────────────────────────────────────────────────
   Wind streaks  (right → left drift)
───────────────────────────────────────────────────────── */
.wind-streak {
  position: absolute;
  left: 110%;
  background: linear-gradient(
    to right,
    transparent   0%,
    @accentColor  28%,
    @accentHover  50%,
    @accentColor  72%,
    transparent  100%
  );
  opacity: 0;
  animation-name:            wind-drift;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  will-change: transform, opacity;
}

@keyframes wind-drift {
  0%   { transform: translateX(0);       opacity: 0;    }
  6%   {                                 opacity: 0.09; }
  85%  {                                 opacity: 0.05; }
  100% { transform: translateX(-135vw);  opacity: 0;    }
}

/* ─────────────────────────────────────────────────────────
   Slash arc wrappers
───────────────────────────────────────────────────────── */
.slash-wrap {
  position: absolute;
  width: 300px;
  height: 100px;
  transform-origin: left center;
  overflow: visible;
}

.slash-svg {
  width: 100%;
  height: 100%;
  overflow: visible;
}

/* ── Shared path rules ──── */
.s-glow,
.s-body,
.s-core {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  opacity: 0;
  animation-name:            slash-draw;
  animation-timing-function: ease-out;
  animation-iteration-count: infinite;
  /* animation-duration / animation-delay come from inline :style */
}

/* Outer blurred orange glow — gives the broad luminous halo */
.s-glow {
  stroke: #ff5500;
  stroke-width: 16;
  filter: blur(6px);
}

/* Amber mid-body — the warm visible core of the slash */
.s-body {
  stroke: #ffb040;
  stroke-width: 4;
  filter: blur(0.6px);
}

/* White-hot inner edge — sharpest, thinnest line */
.s-core {
  stroke: #fff8e6;
  stroke-width: 1.4;
}

/* ─────────────────────────────────────────────────────────
   Slash draw keyframe
   stroke-dashoffset 1→0  =  path draws from start to end
   Then hold, then fade, then snap back invisible for next cycle
───────────────────────────────────────────────────────── */
@keyframes slash-draw {
  0%, 1%  {
    stroke-dashoffset: 1;
    opacity: 0;
  }
  5% {
    stroke-dashoffset: 0.05;
    opacity: 1;
  }
  8% {
    stroke-dashoffset: 0;
    opacity: 1;
  }
  22% {
    stroke-dashoffset: 0;
    opacity: 0.75;
  }
  38% {
    stroke-dashoffset: 0;
    opacity: 0;
  }
  39%, 100% {
    stroke-dashoffset: 1;
    opacity: 0;
  }
}
</style>
